	(1784544867008445, 1784265252790, 1784288140878000, 1784288490446159, '医院探望装', '["1-1"]', '深蓝色休闲夹克，内搭灰色圆领T恤，浅色直筒长裤，脚穿棕色休闲皮鞋。', '', 1784544867008, 1784544867008),
	(1784544867009393, 1784265252790, 1784288140878000, 1784288490423183, '重伤绷带', '["1-1"]', '全身缠绕白色医用绷带，皮肤上粘贴多个电极片，连接透明塑料管线。', '', 1784544867009, 1784544867009),
	(1784544867010021, 1784265252790, 1784288140878000, 1784288490423183, '武馆练功服', '["1-2", "1-3", "1-4"]', '白色棉麻中式练功服，立领盘扣，长袖，上衣宽松，下配同色收口练功裤，脚穿黑色布鞋。', '', 1784544867010, 1784544867010),
	(1784544867010547, 1784265252790, 1784288140878000, 1784288490423183, '按摩状态', '["1-5", "1-6"]', '上身赤裸，下穿黑色宽松运动短裤，肩颈和背部残留翠绿色营养膏痕迹。', '', 1784544867010, 1784544867010),
	(1784544867011163, 1784265252790, 1784288140878000, 1784288490444637, '武馆练功服', '["1-2", "1-3"]', '白色棉麻中式练功服，立领盘扣，长袖，上衣宽松，下配同色收口练功裤，脚穿黑色布鞋。', '', 1784544867011, 1784544867011),
	(1784544867011741, 1784265252790, 1784288140878000, 1784288490442415, '武馆练功服', '["1-2"]', '白色棉麻中式练功服，立领盘扣，长袖，上衣宽松，下配同色收口练功裤，脚穿黑色布鞋。', '', 1784544867011, 1784544867011),
	(1784544867012216, 1784265252790, 1784288140878000, 1784288490439088, '按摩师服', '["1-3", "1-4", "1-5", "1-6"]', '简约白色棉质衬衫，纽扣扣至领口，下摆束入黑色直筒长裤，腰部系黑色细皮带，脚穿白色帆布鞋，长发扎成低马尾，几缕碎发。', '', 1784544867012, 1784544867012);


