INSERT INTO toonflow.events VALUES
	(1784270136252000, '临死得知画作真相', '王闲与友人对质后，得知高三收到的鼓励自己的画实为叶弥月而非陈玉婷所送，心神震荡下含恨而终。', 1784285580176),
	(1784270136252001, '重生至灾难日武馆', '王闲在北拳武馆醒来，与三叔和二哥互动后，确认自己重生到叶弥月遇难的当日，暗下决心改变命运。', 1784285580179),
	(1784270136252002, '按摩房初遇叶弥月', '王闲被二哥带到按摩房，听见8号按摩师怯生生的声音，瞬间认出对方就是前世错过且即将遇难的叶弥月。', 1784285580180),
	(1784270136311000, '王闲威胁校花用脚按摩', '王闲以曝光兼职身份要挟叶弥月，迫使其同意用脚为他服务。叶弥月挣扎后妥协卷起裤腿，将脚放到床上。', 1784285597582),
	(1784270136311001, '王闲察觉叶弥月王级天赋', '王闲借闻味道仔细查看，发现叶弥月脚底的罕见武道灵纹，推断其至少王级天赋，未来可成七境大宗师。', 1784285597586),
	(1784270136311002, '王闲命叶弥月换上黑丝', '王闲以男女授受不亲和保护为由，从抽屉取出黑色丝袜让叶弥月换上，叶弥月羞怒瞪视，未明确应允。', 1784285597587),
	(1784270136313000, '传授混元呼吸法', '王闲教授叶弥月混元呼吸法口诀并逐句解析，叶弥月掌握后桩姿稳固，为提升武道根基埋下伏笔。', 1784285599794),
	(1784270136313001, '故意使叶弥月跌倒', '王闲侧身让叶弥月踩空跌倒，借机质问其色诱，令叶弥月羞愧无措，强化心理优势。', 1784285599796),
	(1784270136313002, '威胁叶弥月长期服务', '王闲用三万卡和校园论坛曝光作要挟，迫使叶弥月同意每周按摩服务，确立长期控制关系。', 1784285599797),
	(1784270136320000, '王闲冲入灾难区', '王闲在众人注视下突然冲出越过栏杆进入灾难区，引起周围人群惊愕和负面议论。', 1784285601413),
	(1784270136320001, '大汉怒斥并挺身而出', '大汉喝止众人恶言，强调武者勇气，随后决定冲入灾难区救人。', 1784285601418),
	(1784270136320002, '武者们艰难进入禁区', '大汉与几位三境武者进入灾难区，感受威压和煞气，举步维艰，决定寻找尸体。', 1784285601420),
	(1784270136320003, '王闲启动星空炼体术', '王闲在灾难区奔跑，认出煞气为灵煞，发现已开阳维脉可吸收，启动星空炼体术修炼。', 1784285601422),
	(1784270136323000, '王闲借灵煞淬炼神脉', '王闲行走间吸收灵煞，忍受经脉破坏重组的剧痛，以星空炼体术将阳维脉修炼成神脉，力量逐步提升，为救援积蓄实力。', 1784285604336),
	(1784270136323001, '踩羽毛吸收灵煞成神脉', '王闲踩住风王隼羽毛，击溃残留意志，全力吸收灵煞，练成阳维神脉，拳力破千斤，整体战力大幅跃升。', 1784285604338),
	(1784270136323002, '大汉暗中观察被惊退', '三境武者大汉目睹王闲无视煞气和S级异兽意志，被王闲察觉后惊恐万分，放弃任务撤退，侧面凸显主角非凡。', 1784285604341),
	(1784270136323003, '王闲火海救小女孩', '王闲挥动羽毛分开火海，跃上三楼阳台，发现被困的小女孩，主动伸手表示带她离开，救援主线正式启动。', 1784285604343),
	(1784270136319000, '爆炸后紧急避难', 'S级异兽空袭导致商业街瞬间化为废墟，广播通知市民前往防空洞避难，王闲与叶弥月随人群排队转移。', 1784285605939),
	(1784270136319001, '废墟孩童无人救援', '众人发现废墟阳台有幸存小孩，三境武者大汉以生命力不足和煞气危险为由拒绝救援，周围人纷纷附和，暴露群体恐惧。', 1784285605940),
	(1784270136319002, '王闲立志跨越栏杆', '王闲拿出武神画纸，向叶弥月宣示守护信念，说服对方后毅然翻越栏杆冲入废墟救小孩，展现主角觉醒的决心。', 1784285605942),
	(1784270136315000, '王闲送营养膏激励叶弥月', '王闲将天宝营养膏递给叶弥月，指出她筋骨松散、力软气短，怕下次按摩时她体力不支占便宜，为提升陪练质量让她服用。叶弥月内心不服却无奈接受。', 1784285616301),
	(1784270136315001, '陈玉婷炫耀武馆特权', '陈玉婷带闺蜜在武馆内宣称能让王闲免费陪练、器材随便用，闺蜜们轻视武馆小破、旧武学落后，引起其他学员不满，凸显其绿茶与炫耀心态。', 1784285616302),
	(1784270136315002, '王闲拒免费陪练并收费', '陈玉婷要求陪练，王闲让二哥报出套餐价格并要求付款，警告闺蜜器材需缴费，直言现有陪练对象，交了钱也得靠后，陈玉婷羞怒交加，冲突爆发。', 1784285616304),
	(1784270136315003, '叶弥月出场惊呆陈玉婷', '陈玉婷嘲讽王闲无人肯找他陪练，王闲侧身露出换好练功服的叶弥月，陈玉婷三人看到校花竟在此陪练，当场震惊，形成强烈反差打击。', 1784285616305),
	(1784270136325000, '王闲废墟中救起等待父亲的小女孩', '小女孩在废墟中等待父亲，王闲出现表示要救她，两人对话中王闲阐明救人缘由，展现主角的勇气与善良。', 1784285619795),
	(1784270136325001, '王闲拒绝抱小女孩最终背她离开', '小女孩要求抱着离开，王闲拒绝并提起她，后经对话妥协背起她，互动中体现两人性格差异和幽默。', 1784285619799),
	(1784270136325002, '救援队宣告无望后王闲走出灾区', '救援队队长汇报灾区无人生还，叶弥月失望之际，废墟中王闲背着小女孩走出，带来震撼和希望。', 1784285619801),
	(1784270136317000, '叶弥月现身威慑陈玉婷', '叶弥月面无表情出现，陈玉婷被气质所慑后退，王闲趁机拒绝带早餐，陈玉婷气愤离开，推动王闲人物转变。', 1784285620759),
	(1784270136317001, '王闲跟随叶弥月至地铁口', '王闲以顺路为由跟随叶弥月，两人在地铁口驻足，叶弥月试图阻止跟随，王闲神情凝重望天空。', 1784285620762),
	(1784270136317002, '风王隼飞掠引发全城恐慌', '风王隼飞过蓉城上空，释放领域威压使行人凝滞恐惧，王闲忆起其特性与前世处理，担忧城市防护不足。', 1784285620764),
	(1784270136309000, '王闲识破叶弥月伪装', '王闲通过声音和体貌认出8号技师是校花叶弥月，揭穿后叶弥月惊慌欲逃，却被反锁门内，被迫面对，建立人物关系与信件伏笔。', 1784285622596),
	(1784270136309001, '王闲逼迫校花按摩服务', '王闲逼迫叶弥月脱衣按摩，指导她用健体拳手法和天宝营养膏，叶弥月疲惫不堪，显示其武道资质，展示主角重生后的控制力。', 1784285622599),
	(1784270136309002, '王闲提议用脚加钟', '叶弥月按摩后手酸无力，王闲要求加钟遭拒，便提议让她用脚继续服务，极具挑衅意味，推动气氛升级和权力动态。', 1784285622601);


